function G(L,a){const c=document.createElement("canvas"),r=c.getContext("2d",{willReadFrequently:!0});if(!r)return{};const o=128,n=72;c.width=o,c.height=n;try{r.drawImage(L,0,0,o,n);const e=r.getImageData(0,0,o,n).data;let h=0,d=0,l=0,u=255,i=0;for(let t=0;t<e.length;t+=4){const v=e[t],C=e[t+1],w=e[t+2];h+=v,d+=C,l+=w;const s=.299*v+.587*C+.114*w;s<u&&(u=s),s>i&&(i=s)}const m=o*n,x=h/m,R=d/m,f=l/m,D=(f-x)*.5,S=Math.max(-100,Math.min(100,(a?.temperature||0)+D)),y=(128-(.299*x+.587*R+.114*f))*.5,A=Math.max(-100,Math.min(100,(a?.exposure||0)+y)),p=i-u;let M=0;p>0&&(M=(235/p-1)*50);const B=Math.max(0,Math.min(200,(a?.contrast||100)+M));return{temperature:Math.round(S),exposure:Math.round(A),contrast:Math.round(B),saturation:a?.saturation||100,tint:a?.tint||0}}catch(g){return console.error("Auto-Color failed:",g),{}}}export{G as calculateAutoColor};
